Review this Go message-processing change for distributed correctness. Publish retries at most three times internally; Handle attempts Apply at most three times per delivery; the broker makes at most five total deliveries when a message is not acknowledged. UpdateAggregate is not idempotent. Report only must-fix findings, each with a reachable failure schedule and the repair invariant; do not implement the change.

func (c *Consumer) Handle(ctx context.Context, message Message) error {
    for attempt := 0; attempt < 3; attempt++ {
        if err := c.service.Apply(ctx, message); err == nil {
            return c.broker.Ack(ctx, message)
        }
    }
    return ErrRetry
}

func (s *Service) Apply(ctx context.Context, message Message) error {
    seen, err := s.inbox.Seen(ctx, message.ID)
    if err != nil { return err }
    if seen { return nil }

    tx, err := s.db.BeginTx(ctx, nil)
    if err != nil { return err }
    defer tx.Rollback()
    if err := UpdateAggregate(ctx, tx, message); err != nil { return err }
    if err := tx.Commit(); err != nil { return err }

    event := Event{ID: uuid.NewString(), MessageID: message.ID}
    if err := s.bus.Publish(ctx, event); err != nil { return err }
    return s.inbox.Record(ctx, message.ID)
}

